INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('eight-princes','八王之乱','politics','span',NULL,'year','year','291–306年，诸王争权，国力大损',NULL,NULL,NULL,NULL,291,1,NULL,3492,306,12,NULL,3683,'西晋宗室诸王相互攻伐，中央权威崩溃，为五胡乱华埋下祸根。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('feishui-battle','淝水之战','battle','point','year',NULL,NULL,'太元八年，383年，前秦败于东晋',383,12,NULL,4607,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'苻坚率百万大军南征东晋，于淝水惨败，前秦迅速崩溃，北方再分裂。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('fu-jian-unify-north','苻坚统一北方','politics','span',NULL,'year','year','370–376年，前秦先后灭前燕、前凉等',NULL,NULL,NULL,NULL,370,1,NULL,4440,376,1,NULL,4512,'苻坚任用王猛，先后灭前燕、前凉等，统一北方，为十六国最大疆域。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('huan-wen-expeditions','桓温北伐','battle','span',NULL,'year','year','354、356、369年三次北伐',NULL,NULL,NULL,NULL,354,1,NULL,4248,369,1,NULL,4428,'桓温三次北伐，一度逼近长安，但最终未能恢复中原。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('jin-unify-wu','三国归晋','politics','point','month',NULL,NULL,'太康元年四月，280年',280,4,NULL,3363,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晋军灭东吴，三国分裂终结，西晋完成统一。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('li-shou-change-country-name','李寿改国号为汉','politics','point','year',NULL,NULL,'咸康四年夏四月（原历），公元338年',338,12,NULL,4067,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'李寿发动政变废杀李期并即皇帝位，随后废“成”号、改国号为“汉”，改元汉兴，以承续汉朝统绪。改号后的政权仍是原成都政权的延续，后世为与其他汉政权区别而合称成汉；其后仍与东晋、后赵周旋，最终于347年为东晋桓温所灭。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('liu-yao-change-country-name','刘曜改国号为赵','politics','point','year',NULL,NULL,'光初二年六月，319年',319,12,NULL,3839,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘曜迁都长安后下令议改汉赵宗庙与国号，群臣据其功业及中山分野建议称“大赵”；刘曜采纳，并以冒顿配天、刘渊配上帝，汉赵由此改称赵，后世称前赵。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('liu-yu-north','刘裕北伐','battle','point','year',NULL,NULL,'416–417年，刘裕灭后秦',417,12,NULL,5015,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘裕率军北伐，攻占长安，灭后秦，东晋势力达于极北。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('wuhu-chaos','五胡乱华','politics','span',NULL,'year','year','304年起诸胡纷纷立国，中原长期战乱',NULL,NULL,NULL,NULL,304,1,NULL,3648,439,1,NULL,5268,'匈奴、羯、氐、羌、鲜卑等族内迁并建立政权，北方长期分裂混战。',NULL,NULL);
